/*
 * standard-delivery contract.js: the contract table of the
 * standard-delivery workflow, one row per step rule.
 *
 * Outputs
 *   contractRows()  an array of {id, step, check, rule}: id is SD-NN, step
 *                   the step the rule governs, check the function of the
 *                   built script that enforces it, and rule one sentence.
 *
 * Invariants
 *   Each row has one test in tests/workflow-scripts/standard-delivery.test.mjs,
 *   which loads this file with loadLibs and requires each check to be a
 *   function of the built script, not of main.js: a check can live in main.js
 *   or in any module the build bundles.
 *   The build bundles every .js file of this directory but this one, so this
 *   file never reaches the built script.
 *
 * Why
 *   The rows are test data, so keeping them out of the built script leaves
 *   its character budget to the code that runs.
 */

function contractRows() {
  return [
    { id: 'SD-01', step: 'Launch', check: 'readDeliveryLaunch', rule: 'The request is a non-blank string, trunk and references are read through args.js, whose resume_args guard refuses args that hold a resume_args key and whose build check refuses a resume of another build, and the trunk passes isGitIdentifier, or the run blocks before any agent call.' },
    { id: 'SD-02', step: 'Facts', check: 'checkDeliveryFacts', rule: 'The facts runner runs the gather-facts command, --trunk and then --ref with each reference, with no --remote, from its command block, and RELAY_SCHEMA, not the prompt, says to relay its outcome and stdout word for word; a relay that is blocked or fails its schema or gatherFactsRoutingSpec() stops through stopDelivery with isReplan true: one that fails its schema or that spec, and a blocked one readRelayAction gives report for, a relay that gives no reason or holds a synapse-gate denial, ends the run blocked with the report Next line, and any other blocked relay pauses with the fix_cause brief, and the reply starts a new pass from the facts step with the answers block, outside maxReplans(), and through describeUnusableResult a null result, an agent failure, adds the describeNoResult sentence once and ends the run with the run_again Next line.' },
    { id: 'SD-03', step: 'Facts', check: 'isConsistentFactsRelay', rule: 'The relayed lines agree with each other and with the launch trunk, or the run blocks as malformed facts.' },
    { id: 'SD-04', step: 'Facts', check: 'checkDeliveryFacts', rule: 'A cut other than none pauses the run before the scan and before planning, naming the fields cut, and the reply starts a new pass from the facts step.' },
    { id: 'SD-05', step: 'Facts to plan', check: 'describeDeliveryStops', rule: 'A delivery stop pauses the run before planning, naming each stop in fixed plain wording, at most maxListedItems() stop lines then a count of the rest, and the reply starts a new pass from the facts step; dirty paths say the run never commits, stashes or discards an edit it did not make.' },
    { id: 'SD-06', step: 'Scan', check: 'runPassScan', rule: 'When external_texts is above 0 the shared scan step runs on model sonnet before planning: a scan that fits its schema and flags an injection suspect is a terminal cause that ends the run, and a coverage failure or a result that fails its schema ends the run blocked with the report Next line, as every unusable result does; runPassScan returns its cause or undefined on every pass, and on pass 1 it calls agent() with the prompt, options and label scan of lib/facts.js runScanStep, byte for byte, so a resumed run replays the cached result, and through describeUnusableResult a null result, an agent failure, adds the describeNoResult sentence once and ends the run with the run_again Next line.' },
    { id: 'SD-07', step: 'Plan', check: 'runDeliveryPass', rule: 'Every planner call follows the facts step of its own pass, and a pass starts only at launch, after needs_replan, after a branch switch, after a taken local review escalation or root cluster, after a reply to a tail ask other than a local review question, or after a reply to a stop with isReplan true, which counts against no replan limit; a taken local review call starts no pass.' },
    { id: 'SD-08', step: 'Plan', check: 'describePlanProblem', rule: 'The plan result fits the schema of its call, the plan result schema or on a revise pass that schema with settled, before any of its fields is read, every value at a field PLAN_SCHEMA marks as a repository path passes isRepositoryPath, the molt.sh files rule, before computeWave, its steps pass computeWave, its trunk_freshness equals the facts, its branch, its base and each versioning.artifact_files path also pass isGitIdentifier, no validation_commands entry is blank or holds a line break or another control character, each refusal naming the entry and its reason, each number of the optional closes is the number of one of the launch references, the refusal naming its index (SD-76), when the facts were taken on a branch other than trunk its branch equals that branch, and its branch matches ^(feature|bugfix|hotfix|refactor|chore|docs|test|ci)/[a-z0-9]+(-[a-z0-9]+)*$, the Branch Taxonomy and Branch Naming of workflow.md, and its title, cleaned as the pull request title is, does not start with a commitTypeMap() value, an optional parenthesized scope, an optional ! and a colon, and buildTitleText(plan), the text the pull request title carries after its type, is not empty, each a refusal with a fixed message that names no title text; before the check, normalizePlanTitle cuts from a copy of a complete result that fits its schema a leading title type that equals commitTypeMap()[plan.classification] in any letter case, with an optional parenthesized scope, ! only when plan.breaking, and a colon, when non-blank text is left after it, and never changes the agent result, so any other typed title is still refused; a result that is not an object is refused as no result; each problem goes back to the planner through callCheckedPlanner (SD-81), except that a null result, an agent failure, adds the describeNoResult sentence once and ends the run, and a planner\'s blocked outcome that fits its schema and gives a reason pauses through stopDelivery with isReplan true and the fix_cause brief; a run started on a branch other than trunk whose name is outside the Branch Taxonomy pauses with the fix_cause brief before the plan call.' },
    { id: 'SD-09', step: 'Plan', check: 'runPlanningPass', rule: 'Planner questions resolve through decide() kind planner_question and the plan through kind plan_acceptance; a pass puts its asks in one pause and the reply goes to a revise pass whose settled enum holds the shown labels Q1..Qn, where only the keys of the shown questions named in settled count as answered; once that revise passes the plan check, and before any rescope, the reply goes into run.answerLog with the settled labels it names, [] when it names none; a plan acceptance is shown only when no other ask is open, and once settled the shown plan result runs; a settled plan_acceptance, remediation_plan_acceptance or trunk_stale question back in its pass is a terminal cause with next action report that ends the run blocked as a workflow defect with no pause; there is no pause limit, so a question still open after any number of rounds pauses again; a plan or revise problem reaches stopDelivery with isReplan true: a null result, an agent failure, ends through describeUnusableResult with the run_again Next line, a planner\'s blocked outcome that fits its schema and gives a reason pauses with the fix_cause brief, its reply starting a new pass, and any other problem goes back to the planner with the check block, at most maxCheckRetries() times, and one still failing ends the run, terminal with the report Next line (describeCheckLimit, SD-81), and a rescope problem stops as SD-59 says; a revise that stops on the plan check first logs its reply with settled [], so a pause asks the next round, and a revise that a retry fixed logs the settled labels of the fixed result; a planner question whose recommended option has beyond_request true, with strength strong and effort trivial or small, is taken and listed under beyond_request where its table cell is auto and asked table_surface where it is surface, and any other such question is a defect decide() refuses, which goes back to the planner (SD-81) and is never asked; an asked one\'s option line says This goes beyond what you asked for.' },
    { id: 'SD-10', step: 'Plan to branch', check: 'resolveTrunkFreshness', rule: 'Trunk freshness fresh gives fresh and no_remote gives skipped; every other value resolves through decide() kind trunk_stale, where a take gives stale and is listed and an ask pauses.' },
    { id: 'SD-11', step: 'Plan to waves', check: 'resolveExternalEffects', rule: 'Before the first wave each irreversible effect a step declares asks through decide() kind external_effect with its summary as verbatim data, shown whole through encodeUntrustedText in a question that names no step id; an effect question the reply settled is not asked again, one it did not settle or whose summary changed is asked again before any wave, and reversible effects are listed in the final message.' },
    { id: 'SD-12', step: 'Branch', check: 'checkBranchRelay', rule: 'The branch runner runs the create-working-branch command with --base, --branch (the plan branch), --classification, --trunk-freshness and --trunk, those values in its command block only, and its stdout parses with the create-working-branch spec, with a branch line equal to the plan branch; a blocked relay, a create-working-branch refusal, and a branch other than the plan branch are terminal causes that end the run, a blocked relay with the fix line unless readRelayAction gives report for no reason or a synapse-gate denial, any other unusable relay, malformed routing lines among them, is report and ends the run blocked through stopDelivery with the report Next line, and through describeUnusableResult a null result, an agent failure, adds the describeNoResult sentence once and ends the run with the run_again Next line.' },
    { id: 'SD-13', step: 'Branch', check: 'needsBranchReplan', rule: 'A branch step that switched onto an existing branch the facts were not taken on, or whose commit differs from the facts head, sends the run back through facts and planning before any wave; a second switch in the run is a terminal cause that ends the run through stopDelivery.' },
    { id: 'SD-14', step: 'Waves', check: 'runPlanWaves', rule: 'Each wave comes from computeWave over the plan steps and the done ids; its workers run in parallel() with their step, wave_scopes, plan_summary and git blocks as data under the boundary sentence and the data line, the file scope and git rules being those of drone.md, changeling.md and safety-rails.md; the loop reads every worker outcome before the wave commit, a null result counting as blocked with a reason that names the agent failure in the describeNoResult sentence and next action run_again, passes the one describeBlockedWave cause of a blocked wave to runCommitStep, which stops with it through stopDelivery as a replan, and handles needs_replan only after a successful commit; the blocked variant of WORKER_SCHEMA carries an optional stage, a string of at most 40 code points naming the Worker Report stage, shared with the blocked variant of the fix gate edit schema, and an optional destructive list built by buildDestructiveListSchema, at most 4 entries {category, item}, category an integer 1 to 10 and item a string of at most 160 code points, and a plan that cannot be scheduled mid-run is report and ends the run blocked with the report Next line and no question.' },
    { id: 'SD-15', step: 'A wave to its commit', check: 'runCommitStep', rule: 'After every wave the commit runner runs the molt command with --trunk and --inputs .hivemind/molt-inputs-<stem>-<label>.json (SD-74), its inputs_file block content holding the commit type mapped from the classification, breaking, the subject of SD-66 and the wave files, every key a field molt.sh takes; its stdout parses with the molt spec with a branch line equal to the plan branch, and a blocked commit gives a cause of one lead line naming its blocker, then at most maxListedItems() outside lines and a count of the rest; through describeUnusableResult a null result, an agent failure, adds the describeNoResult sentence and next action run_again, any other unusable result, malformed routing lines among them, gets report, and a blocked commit relay keeps the fix line unless readRelayAction gives report for no reason or a synapse-gate denial; the wave, fix and review steps read their own result before the commit and pass its causes to runCommitStep, which stops through stopDelivery, isReplan true for a wave and false for a gate step: a commit problem with the step causes then the commit cause, and a made commit with step causes with those causes and the line naming the commit as an end line only when committed is true, so a commit stop never hides a step cause and each agent failure sentence shows once; a commit relay that held passes its commit line to observeHead (SD-72) before any stop; a blocked commit relay, the commit script refusing, and a branch other than the plan branch are terminal and end the run, an agent failure ends it, so does a commit or step stop whose lead cause is report or run_again, and every other commit or step stop pauses, so runCommitStep returns {values}, {result}, {replan} or {rerun: true, stopAnswer}.' },
    { id: 'SD-16', step: 'Waves', check: 'describeBlockedWave', rule: 'readWorkerOutcome types a blocked worker through readGateHold with run.approvals: report when its blocker gives no reason, so no stop asks to clear a cause it does not name; for a hold, its stage destructive-fix-gate or its blocker starting with proposed fix requires human confirmation, the stage and blocker security-policy.md gives the gate and report-format.md lists, approve carrying only its listed items not yet approved, or report when it lists none or only approved ones; else its own next_action; a blocked or failed worker stops the run after the wave commit with one cause: a lead line naming the stop after its wave, then one line per blocked step in orderStopCauses order up to maxListedItems() and a count of the rest, an approve step saying it waits for your approval at the destructive-fix gate and a report hold that it stopped at the destructive-fix gate with no change the run can approve, the first giving the next action, so run_again only when every blocked worker says so, the {stepId, category, item} holds of every approve step on an approve cause, and agentFailure when any blocked worker had a null result; a wave with an agent failure, or whose cause is report or run_again, ends the run, the commit end, when the wave commit made a commit, its own block after the Next line, and a blocked wave whose cause is approve or fix_cause pauses with the commit end as a line of its lead, and the reply starts a new pass that does not count against maxReplans().' },
    { id: 'SD-17', step: 'A wave to planning', check: 'requestStepReplan', rule: 'A needs_replan wave is committed, then the run gathers facts and plans what is left with the done ids reset, at most maxReplans() times; a needs_replan after that asks one step_stop question of type fix_cause whose lead names the limit and the worker reasons, and the reply starts a new pass with those reasons that does not count against maxReplans(), so a needs_replan at the limit again asks again.' },
    { id: 'SD-18', step: 'Prompts', check: 'runnerReadOnlySentence', rule: 'Runner prompts carry no request text; the scan and validation drones carry the runner read-only sentence, only the trigger words of the read-only exemption in ${CLAUDE_PLUGIN_ROOT}/agents/drone.md, and no runner prompt carries an exemption, a skill or a tool sentence.' },
    { id: 'SD-19', step: 'Result', check: 'buildRunRecordParts', rule: 'No message and no pull request text lists the commits: the branch and the pull request on GitHub hold them (ADR-0037 decision 2); the pull request body and comment carry every part buildRunRecordParts() returns, in its order: on a draft (SD-83) the plain draft line, the reversible effects, each gate, on a draft the open findings, the slow test cases of gates.slow when it is not empty, and every taken decision isShownDecision shows, one whose listed (the listReasons() names decide() gave) is not empty or whose kind is not a routineDecisionKinds() kind (plan_acceptance, remediation_plan_acceptance, gate_rerun), the decisions in full there and one line each in chat, and a run whose only taken decisions are routine and unlisted has no decisions part and no Decided for you block; run.taken keeps every entry; and a resume replays every earlier prompt byte for byte.' },
    { id: 'SD-20', step: 'Pause', check: 'pauseDelivery', rule: 'A pause is its lead, then renderQuestions of its asks, a whole block when an ask is exact or has a destructive option (hasDestructiveOption), so no destructive item is ever cut, with no commit, gate line, taken decision or detail block; a planning pause lead is describePlanLine(plan), its plan line alone, naming no path outside the limits; pauseDelivery throws on an ask whose reason is not in askReasons() or a step_stop ask whose stop is neither approve nor fix_cause, so only the Ask Set pauses; each external_effect ask is exact, so its irreversible effect text shows whole through encodeUntrustedText in every fit tier, and no other ask shows verbatim text, so a plan or remediation plan acceptance shows a short code-built problem and never the plan summary or a pointer to the per-agent results; when the replies fail canCarry the run ends blocked through finishOpenQuestions, stop reason reply_size, and when canShowWhole is false, stop reason exact_text_size, and runs nothing further; that stop is one cause with next action answer through finishDeliveryBlocked, so the message is its lead, the Next line nextStepLine(\'answer\'), the open questions, the branch line naming the encoded branch and its head once a wave ran, then the reversible effects and the shown taken decisions one line each; these are the only open question stops.' },
    { id: 'SD-21', step: 'Version check', check: 'checkVersionRelay', rule: 'When plan.versioning.artifact_files is not empty, the validate drone also invokes hivemind:bump-type once under the version check sentence, with a JSON version block of base, the pass facts trunk_commit, bump_trigger and no_bump_match from plan.versioning, and version_files, and nothing else, and the validate schema requires its relay in a version field under passed, failed and not_run and allows it under blocked; the relayed stdout parses with versionCheckRoutingSpec(), whose keys are the bump-type.sh OUTPUT keys in order with counts as a block, and passes isConsistentVersionRelay; a match holds the gate with a note naming the version, also in a pass after a replan with no fix and no stop; a malformed or unusable relay, and a blocked one readRelayAction gives report for, ends the run blocked through stopDelivery with the report Next line, and any other blocked relay pauses with the fix_cause brief, and the reply runs the head check (SD-73), then validation again with the next count, while a null validation result still ends the run; with no version files the prompt and schema are as before and no bump-type run happens.' },
    { id: 'SD-22', step: 'Version question', check: 'askVersionQuestion', rule: 'While run.versionAnswer is unset, a version_check of undetermined or unreadable asks version_bump_indeterminable through buildUndecidedAsk, which decide() asks table_surface at every level, with a code-built brief that fits BRIEF_SCHEMA with strength none: for undetermined the options are a major, minor and patch bump and no bump, each naming the version it gives when trunk_version is known, and for unreadable the problem names the formats the check reads and the options keep the branch version or set the version the reply names; the reply becomes run.versionAnswer and runs one fix round with the version_files and user_answer blocks and no resume note, outside decide() and the round limit, and never a new pass; once run.versionAnswer is set no later version check of the run fails or asks, and the gate note says the version is as the user replied.' },
    { id: 'SD-23', step: 'Tail asks', check: 'askTail', rule: 'Every ask after the last wave pauses through pauseDelivery with its lead and its one question, and pushes nothing: an undecided tail ask, the version question or the fix limit, resolves through buildUndecidedAsk with its call site kind, so its reason comes from decide(), and the gate rerun limit asks nothing (SD-83); askTail pauses with the lead it is given, and with none with a code-built line that every plan step is committed on the encoded branch, naming the head; askTail is askTails of its one ask; a reply goes into run.answerLog through buildAnswerEntry with question the lead text and the questions, labels the shown labels and chosen readReplyChoices of the reply, so a letter reply settles its label and a reply in the user\'s own words settles none, and the same choices update run.approvals (SD-77); a tail question has no question key, so a settled label never skips a step_stop asked again; tail rounds share run.answerLog and the answers round numbering with planning rounds, so a resume replays every earlier agent from cache and takes the reply at the ask; the Next line of an open question stop never offers a pull request from commits a gate did not hold on.' },
    { id: 'SD-25', step: 'Validate', check: 'readValidateOutcome', rule: 'A hivemind:drone on its default model runs validation once per head and edits nothing, and no commit runner follows it, so a dirty path it leaves is refused by the next commit runner or by the dirty check of hivemind:open-plan-pr; when plan.validation_commands is not empty its prompt is the task line, the validation commands sentence, which names no governance doc and makes running each command of the inputs block once, in order and in the foreground, its whole task, not a Worker Self-Check, the runner read-only sentence and slowCaseSentence(), with the commands in a JSON inputs block, and it returns passed, failed with the failures as text, or blocked, as VALIDATE_COMMANDS_SCHEMA says; when the list is empty its prompt is the task line, the validation task sentence, which names the Validation Procedure clause of definitions.md, the runner read-only sentence and slowCaseSentence(), and VALIDATE_SCHEMA also offers not_run, so an empty list never skips validation; both prompts carry a JSON git block holding only plan.base, after any inputs block and before any version block, and both schemas offer slow, at most 20 strings of at most 200 characters, each a test case that passed only when run once more alone, only under passed, so failed, not_run and blocked never carry it; a held validation sets gates.slow to that list or [] when absent, runGates starts it at [], so a later validation on a new head replaces it; passed or not_run holds the gate, not_run is listed, and a blocked result that gives a reason pauses through stopDelivery, whose reply runs the head check (SD-73), then validation again with the next count, and through describeUnusableResult a null result, an agent failure, adds the describeNoResult sentence once and ends the run with the run_again Next line, any other unusable result, a malformed one among them, gets report, and a blocked validation whose blocker gives no reason is report too (readBlockerAction), each ending the run blocked with the report Next line, so no stop asks to clear a cause it does not name.' },
    { id: 'SD-26', step: 'Fix rounds', check: 'runFixRound', rule: 'A failed validation resolves through decide() kind validation_remediation; each taken round is a hivemind:drone under the validation fix sentence, the validation fix task trigger of drone.md, with the failures as data under the boundary sentence, and it reports its files as FIX_SCHEMA says; the commit runner commits exactly those files with the plan commit type; a failed result is kept for the head it ran on, so after a fix round that commits nothing no validate agent runs and the next validation_remediation decision takes the kept failures, counting toward maxFixRounds(); after maxFixRounds() rounds a failure pauses asking, and the reply starts a new pass; a fix round is read before its commit, and a blocked one gives runCommitStep one cause, its reason with its next action, typed through readGateHold with run.approvals like a worker, an approve cause holding the {stepId fix, category, item} of each held item, report when it gives no reason or returned an unusable result, a null fix result naming the agent failure with next action run_again and agentFailure, which ends the run after the fix commit, as a report cause does, while a fix round or fix commit stop led by approve or fix_cause pauses there with the line naming the commit only when one was made, and the reply, an approval reply included, runs the head check (SD-73), which clears the kept failures, so validation runs again with the next count and the next fix round carries the approvals, never a new pass, and the reply, A or B, as user_answer {question, reply} in place of the resume sentence, a version reply taking its place, while no later fix round carries it unless a new fix round stop sets it, so a change the user kept stays refused; while run.versionAnswer is unset, a version mismatch joins a code-built line naming expected_version and the bump to the command failures and gives the fix prompt the version_files block, a version-only failure runs its fix round with no decide() call, counted toward maxFixRounds(), and at the limit pauses through stopDelivery, whose reply resets the round count and runs the head check, then validation again, never a new pass, and fix labels count every fix round of the pass.' },
    { id: 'SD-27', step: 'Gates', check: 'runGates', rule: 'A gate holds only for the commit its step ended on, and validation, which has no commit runner, ends on the head it ran on; a step ending on a commit other than the head the gates last checked sends the run back to the first gate to rerun each gate that held on an earlier commit, each going back resolves once through decide() kind gate_rerun naming only the gates that rerun, after maxGateReruns() of them the run asks nothing and, through resolveGateRerun, opens a draft pull request (SD-83), and the run finishes complete on a ready pull request only when every configured gate held on one commit, naming it, and on a draft only when validation held on that commit.' },
    { id: 'SD-28', step: 'Gate labels', check: 'gateLabel', rule: 'Gate step labels come only from the pass, the gate step and its run count (validate-P-N, fix-P-N, fix-commit-P-N, review-P-N, review-commit-P-N), so every label is unique and a run again replays every prompt byte for byte.' },
    { id: 'SD-29', step: 'Decisions', check: 'resolveDecision', rule: 'Every decide() kind main.js uses, review_question and high_severity_rejection among them, is a *_KIND const and a hard stop or a row of the autonomy table whose resolved_at names a standard-delivery site; step_stop, the kind of every question stopDelivery asks, is a *_KIND const too, and its row surfaces at every level and is resolved at standard-delivery.stop, so decide() asks every stop brief table_surface, a strong one included; decide() is called only in resolveDecision and, through hasDefectQuestion of lib/retry.js, in the planner question check of callCheckedPlanner (SD-81); every undecided question, step_stop, version_bump_indeterminable and the fix limit, goes through buildUndecidedAsk with its call site kind, which resolves through resolveDecision and throws on a take.' },
    { id: 'SD-30', step: 'Launch', check: 'readLocalReview', rule: 'The local_review launch arg is absent, true or false; absent means configured, and any other value stops the run before any agent call.' },
    { id: 'SD-48', step: 'Launch', check: 'readDraft', rule: 'The draft launch arg is absent, true or false; absent means false, any other value stops the run before any agent call, and the value is the draft field of the open-plan-pr inputs_file block.' },
    { id: 'SD-31', step: 'Gates', check: 'configuredGateIds', rule: 'With local_review false the local review gate is not configured: it never runs, never stops the run, never counts as held, the complete message names it as not configured in its gates line, and the pull request body and comment list it as not configured for this run.' },
    { id: 'SD-32', step: 'Validation to local review', check: 'buildReviewPrompt', rule: 'Once validation holds, hivemind:local-reviewer gets base, working_branch, trunk, max_iterations 6 (maxReviewIterations()) and caller_validates true in a JSON inputs block under the boundary sentence and the data line, with no request text and no rule of local-reviewer.md, label review-P-N and phase Review; a review run after a reply to its question also gets user_answer, the question and the reply, in that block, and the data line names that reply as the user decision; a review run after a taken call gets user_answer with decided_by run, and the data line names that reply as the run decision, not the user\'s; when run.approvals is not empty the inputs block also carries it as approvals, the local-reviewer Input Contract key, ahead of user_answer, so with no approval the prompt is byte for byte as before (issue 499); when listAnswerEntries(run) is not empty the inputs block also carries it as answers, after approvals and ahead of user_answer, the task line and data line unchanged, so with no decisions and an empty answer log the prompt is byte for byte as before (issue 531).' },
    { id: 'SD-33', step: 'Review result', check: 'describeReviewProblem', rule: 'The review result fits REVIEW_SCHEMA, whose fields are the local-reviewer Output Contract fields with each Codex-derived text field labelled as able to carry external content, finding_id and each rejected or undone finding_id the one finding id shape of findingIdField(), maxLength 64 and pattern ^[0-9a-f]{8,64}$, recommendation_text with maxLength 200 and allowed empty, blocker with maxLength 300, hypothesized_root 300, root_class 100, same_framing_rationale 600, classification 100, file 400 and title 300, field_excerpt 200 and pattern_category one of P1, P2, P3 or P4, user_question an object of found and ask with maxLength 200, options of 2 to 4 items of id A, B, C or D, summary with maxLength 160 and an optional destructive list built by buildDestructiveListSchema, at most 4 entries {category, item}, category an integer 1 to 10 and item at most 160 code points, recommendation of option_id A to D, strength strong, weak or none and why with maxLength 200, each text labelled so, and the required gate of the booleans irreversible and architectural, with no other key, the required rejected_findings a list of at most 50 objects of finding_id, title and record, the required undone_fixes a list of at most 50 objects of finding_id and title, and the required open_findings a list of at most 50 objects of finding_id and title with maxLength 300, each labelled so, each with no other key, and retry_minutes, an unlabelled integer, the one optional field, allowed only under blocked, and it carries every field its exit_reason names and no conditional field that only another exit_reason names; each conditional list field holds at least one entry and has maxItems, signals_fired and signals_observed 10, conflicting_findings, cluster_files and cluster_ids 20, each cluster_files entry at most 400 and each cluster_ids entry at most 64 code points, and buildReviewFieldSchema throws on a list entry with no maxItems and on a type that states no domain; every count is zero or more, and no conditional field is a count; a user_question whose option ids are not A, B, C, D in that order, which refuses a repeated id, or that recommends no option of its own is refused too; any other result is report and ends the run blocked after the review commit with the report Next line and no question; through describeUnusableResult a null result, an agent failure, ends the run, adds the describeNoResult sentence once and the run_again Next line, and any other unusable result gets report.' },
    { id: 'SD-34', step: 'Local review to its commit', check: 'runReviewGate', rule: 'Whatever the reviewer returned, the commit runner then runs with an empty file list and stops the run on any edit left behind, and the review gate holds on the commit it reports; describeReviewProblem reads the review before the commit and its cause goes to runCommitStep, so an unusable review is never hidden by a commit stop, and a null review commit result gives the run_again Next line only when no cause with the fix line or report leads; a non-null unusable review is report and ends the run blocked after the review commit with the report Next line, so no local review runs again.' },
{ id: 'SD-35', step: 'Review routes', check: 'localReviewRoutes', rule: 'localReviewRoutes() maps every exit_reason of the local-reviewer Output Contract and nothing else, and clean holds the gate. The exits it routes to hold or diminishing are the exits workflow.md (PR Requirements) names as holding, and only the diminishing ones carry its taken condition. The local_review transitions of standard-delivery.json route the same exits: hold to the gate_check decision, diminishing to diminishing_returns_decision, whose only transition to a state that is not terminal is taken, into gate_check. Only local_review clean, diminishing_returns_decision taken and local_review_decision skipped and held transition into gate_check; gate_check held is the only transition into open_pr, gate_check rerun goes back to validate, no path reaches open_pr without gate_check, and the only user gates are brood_confirm and question. gate_check blocked and every diminishing_returns_decision outcome but taken end at a terminal state that never reaches open_pr. localReviewRoutes() routes injection-suspect to stop, max-iterations-reached and break-fix-break to draft (SD-83) and blocked to stop_rerun; the local_review transitions stay as they are, so every stop and draft exit, the asked one included, ends at a terminal state there that never reaches open_pr.' },
    { id: 'SD-36', step: 'Review stops', check: 'describeReviewStop', rule: 'injection-suspect and blocked stop with one line naming the exit and its cause, the head, the iterations and the open finding count, then at most one detail line built in code: injection-suspect names the short finding id and the category in its line and shows the whole excerpt encoded in its detail line, and blocked quotes the blocker with a limit equal to its maxLength 300, so a valid blocker is never cut; through stopDelivery, injection-suspect is terminal and ends the run blocked with no pull request, and a blocked review with no retry_minutes of 1 or more pauses with that stop as the lead of one step_stop question whose reply runs local review again with the next count, its commit runner reading the head (SD-73), while one with it waits (SD-84); either rerun gets fixLedgerPath() as resume_from_ledger, once, set in code and never the review\'s ledger_path, as the next review run after a review replan does (SD-39); max-iterations-reached and break-fix-break never pause and start no pass: each returns {draft} whose reason is its lead, the head and the open finding count, with no detail line, so the pull request opens as a draft (SD-83).' },
    { id: 'SD-37', step: 'Review questions', check: 'askReviewQuestion', rule: 'user-input-required and high-severity-rejection resolve through decide() on a brief built in code from the reviewer option ids, recommendation, strength and gate and the category of each entry of each option\'s destructive list, its item text unshown, with safety false and the recommended option reversible unless the gate says irreversible, so every text is code-built, a valid review never asks as malformed_brief, and a recommended option that lists a destructive change asks gate_safety at every level whose cell is auto, never taken (issue 499); a take, an agreed call that is reversible and not architectural, never pauses and never touches run.answerLog, lists the call in run.taken by its short finding id with the encoded ask and the encoded summary of the chosen option, and reruns the review gate; an ask, the gate irreversible or architectural, strength none or a surface cell, pauses the run with the lead Local review on commit, the head, the finding by the first 8 code points of its finding_id and the encoded found, then the reviewer question: its problem the encoded ask, its options the reviewer options with encoded summaries and each destructive item encoded, its ask items the raw destructive list of each option, so a letter reply approves the chosen option\'s changes through applyApprovalChoices (SD-77), and its recommendation the reviewer option_id and strength with the encoded why, no option and no strength from code, with its ask reason from decide(); the rerun review gets that lead and the question as user_answer.question.' },
    { id: 'SD-38', step: 'Diminishing returns', check: 'resolveDiminishingReturns', rule: 'diminishing-returns resolves through decide() kind diminishing_returns_exit: a take holds the gate and is listed, and an ask pauses the run and the reply starts a new pass.' },
    { id: 'SD-39', step: 'Local review to planning', check: 'requestReviewReplan', rule: 'planner-escalation and root-cluster-suspected resolve through decide() kinds planner_escalation_routing and root_cluster_routing; an ask pauses the run and the reply starts a new pass, and a take starts a new pass through the facts step with replan data projected by projectReplanReview() to exit_reason and only the fields reviewExitFields() names for it, so rejected_findings, undone_fixes, ledger_path and the counts never reach the planner; a take raises run.replans and run.reviewReplans, counted against maxReplans() and maxReviewReplans() 1; at either limit the review is read before any decide() call, so it is neither taken nor asked: requestReviewReplan returns {draft} naming the exit and the limit reached, and the pull request opens as a draft (SD-83); routeLocalReview sets run.resumeLedger before requestReviewReplan, as the blocked rerun does (SD-36), so the next review run gets fixLedgerPath() as resume_from_ledger, once, set in code and never the review\'s ledger_path; every such replan reason asks for the remediation of what the review block reports, and none names a zoom-out.' },
    { id: 'SD-40', step: 'Remediation plan', check: 'resolvePlanAcceptance', rule: 'Once local review sent the run back to planning, which it reads from the run\'s taken planner_escalation_routing or root_cluster_routing decision, every later plan acceptance resolves through decide() kind remediation_plan_acceptance, auto at high and balanced and surface at low; its brief gate copies plan.remediation_gate.promotion_gate (irreversible, architectural, safety) whole, with gate.architectural also true when grows_surface is true, and its problem names each of the five flags that holds, so a plan flagged irreversible, architectural, safety or grows_surface asks with gate_irreversible, gate_architectural or gate_safety through the pause and revise path, and a plan with a clean gate is taken at the default level and, a routine kind, not listed; repeats_surface and a plan file outside the scope limits never ask: resolvePlanAcceptance passes repeats_surface and outside_limits in listed to decide(), so an acceptance it takes keeps its own recommendation and is listed for veto in chat and the pull request body.' },
    { id: 'SD-41', step: 'Gates', check: 'resolveGateRerun', rule: 'A commit the reviewer makes sends the run back through validation, and a commit made after local review held sends it back through validation and local review.' },
    { id: 'SD-42', step: 'Gates to the PR', check: 'buildPullRequestPrompt', rule: 'Once every required gate held on one commit H, the configured gates or, on a draft, validation alone (SD-83), a haiku runner runs the open-plan-pr command once, with label pr-P and phase PR, one runner call inside the gate loop, and each reply to a pause of that step runs the head check (SD-73), then the step again under label pr-P-N, N from 2, with the same inputs when the head did not move and after the gates rerun when it did, with a command of only --head (the plan branch), --base (the plan base), --expect-commit H, --inputs .hivemind/pr-inputs-<stem>-<label>.json and --body-file .hivemind/pr-inputs-<stem>-<label>-body.json (SD-74), an inputs_file block whose content is the JSON text of only title, comment and draft, true when the draft launch arg is true or gates.draft is set (SD-83), and a body_file block whose content is the body as raw text; it is the only push the workflow makes, so every push carries --expect-commit.' },
    { id: 'SD-44', step: 'PR title', check: 'buildPullRequestTitle', rule: 'The title is one line with no control character, plain text with no Markdown wrapper, built from the plan commit type, the breaking marker and plan.title, never from the plan summary, at most maxTitleLength() code points including that prefix, cut at a word boundary only when longer, and never ending in an ellipsis or inside a bracket it opened; for a plan that passed the plan check the text after the prefix, buildTitleText(plan), is never empty (SD-08).' },
    { id: 'SD-45', step: 'PR body and comment', check: 'buildPullRequestTexts', rule: 'The body holds the closing lines of SD-76, the digest paragraph, digest.problem then digest.change through renderText with a blank one left out, a Steps: line with one line per step naming its id, files and outcome through renderText, and the run record, never plan.summary, and the comment its lead and the same run record, which is every part buildRunRecordParts() returns, in its order: on a draft the plain draft line, the reversible effects, each gate with its result and the commit it held on, did not hold for a configured gate with no hold, or not configured for this run, on a draft the open findings of run.open when it is not empty, the slow test cases of gates.slow, one line each under one label, when it is not empty, the buildRejectedFindingsBlock text when run.rejected or run.undone is not empty, its note did not hold when the review gate never held, each run.approvals entry on its own line through renderDestructiveChange under one label, and every taken decision isShownDecision shows, one with a non-empty listed or not of a routineDecisionKinds() kind, as its renderDecisionsCompact line, the question and the chosen option with no why, none when only routine unlisted ones were taken, a taken local review call with its short finding id, encoded ask and encoded chosen summary; neither carries a control character other than newline and tab or a code fence, every external part goes through neutralizePullRequestText, which puts each at-mention, issue reference, owner/repo reference, GH-N reference and http, https or www URL in a single-backtick code span and backslash-escapes each backslash, backtick, [, ], <, > and & elsewhere, the closing lines, the gates, the labels and the comment lead stay plain, a text over maxPullRequestTextLength() characters, or a title, body or comment that holds a forbiddenSubjectTexts() string in any case, checked on the neutralized texts, is a terminal stop that ends the run blocked before any push, naming its size or that text.' },
    { id: 'SD-46', step: 'PR relay', check: 'checkPullRequestRelay', rule: 'The relayed stdout parses with openPlanPrRoutingSpec(), whose keys are the open-plan-pr.sh OUTPUT keys in order and whose warning holds only the script fixed texts, head_ref_oid equals H, and commented is true exactly when created is false; a head_ref_oid other than H is a terminal stop that ends the run blocked; a malformed or other non-null unusable relay is report and ends the run blocked through stopDelivery with the report Next line, as does a blocked relay readRelayAction gives report for, and any other blocked relay pauses with one step_stop question naming the pull request step, and the reply runs the step again; a blocked relay whose stderr holds a synapse-gate denial or an inputs refusal of open-plan-pr.sh (isInputsRefusal, which a parity test pins to that script) is report and says This step pushed nothing., a blocked relay whose stderr holds the line pushed: no says This step pushed nothing. and one holding pushed: yes says the run stopped after this step pushed commit H, each keeping the fix line unless readRelayAction gives report, any other blocked relay keeps the fix line unless readRelayAction gives report, and every other pull request stop says the run did not see whether this step pushed and that taking it again pushes the same commit and reuses a pull request open on it, with no may be guess; the text size and attribution stops are terminal and report; through describeUnusableResult a null result, an agent failure, ends the run, adds the describeNoResult sentence once and the run_again Next line.' },
    { id: 'SD-47', step: 'Result', check: 'finishDeliveryComplete', rule: 'The run finishes complete with pr {url, head_ref_oid, created}, and the final message is one line naming the pull request opened or pushed to and its commit, one line naming the gates that held and any gate not configured, or on a draft the line The pull request is a draft: and its reason (SD-83), the warning line when there is one, the rejected findings block, then the reversible effects and the taken decisions isShownDecision shows, one line each, so no Decided for you block when only routine unlisted ones were taken, and no commit list.' },
    { id: 'SD-49', step: 'Prompts', check: 'addResumeNote', rule: 'Once run.answerLog is not empty, every agent prompt carries resumedReplySentence() as its second line but the scope, plan and revise prompts and the review and fix prompts with user_answer, which carry the replies in data blocks and not the sentence; no prompt sent before the first reply carries it, and no other prompt carries reply text but a review prompt, only inside its inputs block as answers (SD-32).' },
    { id: 'SD-50', step: 'Relays', check: 'describeRelayBlocker', rule: 'Every step- or script-written diagnostic or name a message shows goes through encodeUntrustedText, while planner prose rendered by lib/brief.js shows whole through renderText, one line with no control, line separator or bidi character, so it never starts a line of the question structure, and each option shows the letter optionLabel gives its position; a blocked relay quotes its last non-blank blocker line, else its first two non-blank stderr lines, else gives no reason and is report through readRelayAction, so no stop asks to clear a cause it does not name, each one line cut at a sentence or word boundary to maxExcerptLength() code points, a step blocker goes through describeReason, one line quoted whole up to maxReasonLength() code points and cut at a boundary past it, each cut quote followed by the plain words \', shortened\', never \' (cut)\', and the text starts with a capital letter after a full stop and stays lower case after a colon; every blocked lead the facts, branch, wave, commit and gate steps build is one line naming the step and its cause, and capItemLines() shows at most maxListedItems() delivery stop, dirty path or blocked step lines, then a count of the rest.' },
    { id: 'SD-51', step: 'Result', check: 'finishDeliveryBlocked', rule: 'Every blocked result is finish over its causes, and no caller builds a lead or a Next line: finish puts buildStopBlocks of the causes first, the lead, then nextStepLine() with the lead cause next action as a whole block, then one block per later cause; finishDeliveryBlocked then adds one block per end line, one line naming the encoded branch and its head only once a wave ran, then the reversible effects and the taken decisions isShownDecision shows, one line each; an open question stop and a resume of another build are one cause with next action answer; no block carries shorten, a lead over maxBlockedLeadLength() code points has as its compact form the cutAtBoundary prefix of at most those code points, so it never cuts mid-word, and finish throws only when causes are not given exactly for a blocked outcome and when a complete outcome has no blocks.' },
    { id: 'SD-52', step: 'Question keys', check: 'questionKey', rule: 'A question key holds its kind, its scope and its rendered text: the scope is the pass for planner_question, the pass and the whole plan for both plan acceptances, and run for trunk_stale and external_effect.' },
    { id: 'SD-53', step: 'Message shape', check: 'buildRecordTailBlocks', rule: 'Every pause is a one-line lead, but a step_stop lead holds each cause line and end line, so a planning lead names no outside path, then the questions, and the reply line last; every run end is its lead, followed by the Next line when blocked; no message shows a commit list, a criticality or ask-reason line, a detail block, the plan summary or a word for word section but for an irreversible effect, no pause shows a taken decision, each taken decision takes one line and ends in one terminal mark, every cut quote ends at a sentence or word boundary followed by the words \', shortened\', outside quoted JSON strings no line holds two full stops in a row, a full stop after ! or ?, or \' (cut)\', no full finding id appears, and each message stays within the fixed bound the test states.' },
    { id: 'SD-54', step: 'Next action', check: 'buildStopBlocks', rule: 'WORKER_SCHEMA, the fix gate edit schema, VALIDATE_SCHEMA and VALIDATE_COMMANDS_SCHEMA each carry an optional next_action of fix_cause or run_again, only with outcome blocked; there are five next actions, and answer, approve and report are set only by code, never by an agent or a schema, approve only by readGateHold, with at least one held item the user has not approved; nextStepLine() starts with Next:, names one action through describeStopAction and points only at the cause of its own lead; it maps fix_cause or no value to the fix line, to clear the cause named above, then run the request again, approve to approving or refusing the change named above, then running the request again with that answer, report to a line saying nothing in your repo needs a fix and to report the stop as a workflow defect, then run the request again, run_again to a fixed line saying nothing in the repo needs a fix, and answer to the line saying to run the request again with the answers in it; one rule covers every step: a null result from any agent() call, an agent failure, gets the describeNoResult sentence once, only through describeUnusableResult, next action run_again and agentFailure true, which no other code sets, and a non-null unusable result gets report; buildStopBlocks orders the causes of a stop through orderStopCauses, stably by approve, fix_cause or no value, answer, report, then run_again, and its Next line is that of its first cause, so run_again only when every cause is run_again, so a lone agent failure ends with the sentence in its first block and nextStepLine(\'run_again\') as its second, and a compound stop shows every cause with each agent failure sentence once; a blocked wave uses run_again only when every blocked worker says run_again.' },
    { id: 'SD-55', step: 'Rejected findings', check: 'buildRejectedFindingsBlock', rule: 'Every usable review, whatever its exit_reason or pass, adds its rejected_findings and undone_fixes to run.rejected and run.undone before its commit step, each finding_id once in first-seen order, and sets run.open to its open_findings; the review gate note adds the code-built count of findings rejected under recorded decisions, then of findings whose failed fix was undone, each counted from its run list, left out when empty, which the pull request body and comment carry with no rejected-finding text, and the final complete message carries a chat-only rejected findings block right after its gates line and any warning line: one heading line with that note, then one line per rejected finding with only the short id, the first 8 characters of its finding_id, encoded by encodeUntrustedText, then, when a fix was undone, the heading line The findings whose fix it undid: and one line per undone fix the same way; when only undone fixes are listed, the heading line is the note alone, with no rejected-finding line; two empty lists add nothing.' },
    { id: 'SD-56', step: 'Step results', check: 'buildTaggedSchema', rule: 'Every step result schema whose fields depend on its outcome or exit_reason is built by buildTaggedSchema; a result that carries a field of another outcome, or lacks one its outcome requires, fails its check and blocks the step that reads it, and each agent gets the schema through toAgentSchema, with no anyOf.' },
    { id: 'SD-57', step: 'Tail replies', check: 'replanFromTailAsk', rule: 'A reply to a local review question reruns the review gate on the current head with the next gateLabel count and user_answer {question, reply}, and a taken local review call does the same with user_answer {question, reply, decided_by run}, the reply the recommended option id, and the commit runner and localReviewRoutes() apply as for any review run; when that review returns planner-escalation or root-cluster-suspected and its routing is taken, the replan counts against maxReplans() and maxReviewReplans(); a reply to a version question runs one fix round and starts no pass; the reply that ends a wait reruns the review gate with no user_answer and starts no pass (SD-84); a reply to any other tail ask starts a new pass through the facts step that does not count against maxReplans(); a reply to a facts or plan stop of a pass whose replan data carries a review keeps that review in the replan data of the new pass (keepReplanReview), and a pass no review started gets none; no replan data carries an answer, since the answers block holds it.' },
    { id: 'SD-58', step: 'Bounded fields', check: 'describePlanLine', rule: 'No message cuts an agent value: every agent-written string a message shows comes from a step-schema field with maxLength and shows whole, or no message shows it; a planning pause lead is describePlanLine(plan), one line of the encoded branch, which plan-schema.json bounds by maxLength 200, the step count, the distinct plan path count and digest.change made one line, naming no outside path and no limits_reason, and the external effect question names no step id, so no step id is cut; every local review string a message shows has a bound in REVIEW_SCHEMA, whose every list has maxItems, and every message stays within a fixed bound when every unbounded agent field (plan.summary, worker summary, validate failures, and the review strings with no maxLength) holds 5000 characters.' },
    { id: 'SD-59', step: 'Scope', check: 'runScopeStep', rule: 'Every pass runs the scope step once, after the facts step and the scan and before planning: hivemind:cerebrate on SCOPE_MODEL sonnet at effort high, with label scope-P and phase Scope; after the revise of answer round R, unless the reply settled the shown plan acceptance, the pass scopes again with label scope-P-R, whose scope replaces the pass scope for the acceptance check and every later revise prompt of the pass, so a resume replays both from cache; runScopeStep returns {scope} or {problem, nextAction}, which stops through stopDelivery with isReplan true: through describeUnusableResult a null scope-P or scope-P-R result, an agent failure, adds the describeNoResult sentence once and ends the run with the run_again Next line, and any other result that fails SCOPE_SCHEMA goes back to the scope agent with buildCheckFixPrompt and the check block, label scope-P-fix-N or scope-P-R-fix-N for N from 1 to maxCheckRetries(), a fitting retry going on as a fitting first result does, and one still failing returns describeCheckLimit, which ends the run, terminal with the report Next line.' },
    { id: 'SD-60', step: 'Scope prompt', check: 'buildScopePrompt', rule: 'The scope prompt is one task line asking to scope the request for its planner in Scope Mode, then boundarySentence(), dataBlocksSentence(), the facts block and the request block; once listAnswerEntries(run), each launch decision (SD-80) then run.answerLog, is not empty, settledAnswersSentence(), which calls settled only what the settled labels of each entry name, takes the place of the data line and that list follows the request block in an answers block, and the prompt never carries the resume note, so a scope prompt sent before the first reply of a run with no decisions equals that of a run with no answers.' },
    { id: 'SD-61', step: 'Scope result', check: 'buildScopeSchema', rule: 'SCOPE_SCHEMA holds documents[] of {path, line} with an integer line, paths[] of {path, exists, drift} and limits[] of {path, origin} with origin request or answer, so an inferred limit fits no value, all three lists and every item field required, documents holding at most 10 entries and paths and limits at most 30 each by maxItems, each string field but the origin enum starting with externalLabel() and holding a maxLength, and each path field marked with repositoryPathMark().' },
    { id: 'SD-62', step: 'Scope result', check: 'keepRepositoryPathEntries', rule: 'A scope result that fails SCOPE_SCHEMA goes back to the scope agent, and one still failing after maxCheckRetries() retries ends the run before planning, saying the scope step returned a result it could not use; a path that starts with the facts root line and a slash is first made relative to that root, and a root of none converts nothing; an entry whose path then fails isRepositoryPath is dropped from the scope and does not stop the run; a limit path is made relative the same way and loses a trailing slash, the limit keeping its origin and never dropped; a re-scope result that fails SCOPE_SCHEMA goes back and ends the run the same way, after the reply of its round is logged, so each retry prompt carries it; an empty scope lets planning go on.' },
    { id: 'SD-63', step: 'Scope to planning', check: 'buildPlanPrompt', rule: 'The plan and revise prompts carry the checked scope as a scope data block right after the request block, a revise prompt after a re-scope carrying the re-scope result, and the scope never reaches a message, the pull request texts or a worker prompt.' },
    { id: 'SD-64', step: 'Scope Mode', check: 'scopeOptions', rule: 'Scope Mode is the ### Scope Mode section of ${CLAUDE_PLUGIN_ROOT}/agents/cerebrate.md, which owns what a scope holds, and the scope step sends the planner agent there by name only.' },
    { id: 'SD-66', step: 'Commit subject', check: 'toCommitSubject', rule: 'Every commit inputs_file block carries a subject built by code, so the runner reads no git state to write one: a wave of one step gives its outcome, a wave of several gives their ids then the first outcome, made one line and cut by cutAtBoundary to at most maxSubjectLength() 72 code points; the fix round and review commits have fixed subjects; a derived subject that is blank, holds !: or a BREAKING CHANGE marker, or holds an attribution string the molt SKILL.md forbids falls back to a fixed subject naming the wave; every subject passes the molt.sh subject rules.' },
    { id: 'SD-67', step: 'Answer log', check: 'buildPlanPrompt', rule: 'Each reply a pause takes goes once into run.answerLog as {question, settled, reply}, question the pause lead and renderQuestions of the shown asks, settled what buildAnswerEntry derives: for a planning round the shown Q labels the checked revise of its round names, in shown order, or [] when it names none or the revise failed its check, and for a tail round the shown labels readReplyChoices reads from the reply, [] for a reply in the user\'s own words; each planning reply round, logged after its revise or after a failed revise, applies readReplyChoices of its reply to run.approvals (SD-77); every later plan prompt, after a branch, step, tail or review replan alike, carries the whole log in an answers block, and a revise prompt the entries of earlier rounds, each after the launch decision entries listAnswerEntries puts first (SD-80), and the data line calls settled, never asked again or reversed, only what the settled labels of an entry name.' },
    { id: 'SD-68', step: 'Resume build', check: 'readLaunchInputs', rule: 'resume_args carries build, the BUILD_ID of the script that paused; a resume whose build is absent or differs stops blocked before any agent call as one cause with next action answer, whose Next line asks to run the request again with the answers in it, not to fix anything, and a resume of the same build replays every earlier prompt byte for byte.' },
    { id: 'SD-69', step: 'Scope limits', check: 'listOutsidePaths', rule: 'When the checked scope sets limits, a plan path, which listPlanPaths gives as every value at a PLAN_SCHEMA field the repository path mark names, the step files and version files, that is in neither versioning.artifact_files nor versioning.changelog_files and neither equals a limit path nor sits under it plus a slash makes resolvePlanAcceptance pass outside_limits in listed to decide(), so the plan or remediation plan acceptance is taken and listed for veto in chat and the pull request body where its table cell is auto, the default level among them, and asked table_surface only where the cell is surface, keeping its own recommendation either way, since markOutsideLimits never changes its strength or why, its problem naming their count only when it fits the brief bound; no message or pull request text names an outside path or a limits_reason, and the built script reads no limits_reason field; a limit that fails isRepositoryPath matches no file, so the file is listed; empty limits leave the brief as it was and the acceptance unlisted; the limits come only from the scope step, so a later pass whose limits still leave a file outside lists it again, and one whose limits take it in does not; validation fix round and local review edits are not plan paths and are outside the limits.' },
    { id: 'SD-70', step: 'Stops', check: 'stopDelivery', rule: 'stopDelivery(causes, run, endLines, isReplan), endLines [] and isReplan false when left out, ends the run through finishDeliveryBlocked when any cause has terminal true or agentFailure true, mixed causes included, or when the next action of the first cause in orderStopCauses order is not in stopAskActions(), approve and fix_cause, no value read as fix_cause, so a report, run_again or answer lead ends the run blocked with its Next line and asks nothing (issue 549); otherwise it asks through askTails, whose lead is the cause problems in buildStopBlocks order, then the end lines, one per line, with the cutAtBoundary prefix of maxBlockedLeadLength() code points as its compact form when longer; when that first cause is approve, it asks buildApprovalAsks of its holds, one step_stop question per held item, each with stop approve: its problem names the encoded step, option A, Approve this change, lists the encoded item with its category, option B keeps it as it is and plans again or takes the stopped step again without it, strength none, decide() reads a code-built copy with no step id and an unshown item that fits BRIEF_SCHEMA whatever the hold holds, and ask.items is [[the item], []], so only a letter reply choosing A approves it; otherwise it asks one undecided question of kind step_stop, stop fix_cause, through buildUndecidedAsk, table_surface at every level, whose code-built buildStepStopBrief(isReplan) fits BRIEF_SCHEMA with one option, strength strong, says to clear the cause named above and commit any change, then reply, and says whether the reply takes the stopped step again or plans again; a pause returns {result}, and a reply returns {replan: {reason}} when isReplan, a new pass that does not count against maxReplans(), else {rerun: true, stopAnswer}, stopAnswer the {question, reply} askTails returns, which only runFixRound reads (SD-26), never the review gate: the gate loop takes the stopped step again, reading the head first per SD-73; the built script calls finishDeliveryBlocked only in stopDelivery, finishOpenQuestions and the launch end of runDelivery.' },
    { id: 'SD-71', step: 'Runner retry', check: 'runRunnerRelay', rule: 'The facts, branch, commit and pull request runners call agent() through runRunnerRelay: a relay that fits RELAY_SCHEMA with outcome blocked and a stderr isTransientFailure names runs once more under label <label>-retry with the prompt built for that label: the facts and branch prompts are identical, and the commit and pull request prompts differ only in the inputs path and, for the pull request, the body path, so a retry never writes a file of the first call; that relay is read as the first would be; a malformed relay, a non-transient block and a null result are never retried, and no step call retries more than once.' },
    { id: 'SD-72', step: 'Head', check: 'observeHead', rule: 'observeHead(run, commit, branch) is the only code of the built script that writes run.head, run.branch or run.headRound: it sets run.head to commit, run.branch to branch and run.headRound to the run.answerLog length; runCommitStep feeds it the commit of a checked molt relay, and runDeliveryPass the commit of a checked branch relay after needsBranchReplan and before any wave of each pass; the run keeps no commit list.' },
    { id: 'SD-73', step: 'Head check', check: 'runHeadCheck', rule: 'Every reply adds one entry to run.answerLog, so the head is unread exactly when run.headRound is behind run.answerLog.length, whatever route the reply took; while the head is unread, the gate loop runs one head check before validation or the pull request step: runCommitStep with an empty file list, stepName head and label head-P-N, N counting gates.runs.headCheck over the pass, so molt reports the head of the working branch with committed false, and it clears every kept validation failure; local review gets no head check, since its commit runner, the same empty-list molt run, reads the head; a gate holds only while the head is read; a malformed head check is report and ends the run blocked with the report Next line, so no reply runs head-P-N+1, a transient block retries once under head-P-N-retry, a refusal of it is a commit-script refusal and ends the run, a null result ends it, and any other run end it returns is returned as is; when the head moved the gates that held on the old head go through the gate rerun of SD-27, else the same step, gate or pull request, runs again.' },
    { id: 'SD-74', step: 'Runners', check: 'describeCommandStop', rule: 'The facts, branch, commit and pull request runners are hivemind:synapse on RUNNER_MODEL haiku, and the scan, validation and fix rounds are hivemind:drone; a runner prompt is its task line, dataBlocksSentence(), a command block holding the one command line of buildRunnerCommand, for the commit and pull request runners an inputs_file block of {path, content} and for the pull request runner a body_file block of {path, content}, whose block names and {plugin-root} placeholder are the words of ${CLAUDE_PLUGIN_ROOT}/agents/synapse.md, {plugin-root} being its only placeholder; the facts command holds {plugin-root}, and every later runner command holds the plugin_root of the pass\'s checked facts relay in its place, or the placeholder when that value is none (issue 509); the inputs path is built in code from the stem runFactsStep sets from each checked facts relay plus the call label, so, given a faithful facts relay (ADR-0037 issue 487 residual), no two calls of one run or of two runs share a path and a resumed run rebuilds the same path; a pass with no stem has no path, and its --inputs word is a terminal command stop; the pull request body path is the inputs path of the call label and -body, and one whose token passes 64 characters is a --body-file terminal command stop; the commit and pull request steps check the words for both the call label and its retry label; no runner prompt carries a commit or push grant, since synapse commits and pushes under its standing grant in safety-rails.md (Commit Authority), bounded by the hook; before the call each step checks its command words with describeRunnerWordProblem, the value classes of the synapse gate hook, and a word outside its class is a terminal cause with next action report naming its flag and never its value, so no runner call is made; a blocked runner relay whose stderr holds a deny reason of that hook is report through isGateDenial, so it ends the run blocked with the report Next line, which a test pins to the hook\'s deny texts; every command the engine builds is an exact form ${CLAUDE_PLUGIN_ROOT}/hooks/synapse-gate.sh allows for hivemind:synapse.' },
    { id: 'SD-75', step: 'Relays', check: 'readRelayedLines', rule: 'The stdout of the facts, branch, commit and head check, and pull request relays, and of the validation version relay, is read through readRelayedLines with parseRoutingLines; that parser reads only the first line of each spec key at its level, and reads a block line only while its block is open, and a block closes only at the next top-level routing line read, so a line it does not read changes nothing, wherever it sits, before, between, inside a block or after the routing lines, such as a push hint, a code fence, a blank line, agent prose or a repeat of the routing lines (issue 447); the first line of a spec key is read wherever it sits, and a missing required key, or a first line off its pattern, still stops as malformed routing lines, which is report and ends the run blocked.' },
    { id: 'SD-76', step: 'PR closing lines', check: 'renderClosingLines', rule: 'The pull request body opens with one plain line Closes #N for each distinct number of the optional plan.closes, in plan order, plain, ahead of the digest paragraph, so GitHub links each issue it names as closed by the pull request (issue 491); describePlanProblem, through describeClosesProblem as its last check, refuses a number that is not the number of one of run.references, the launch references, with a fixed message naming its index, and checks nothing else about it, since the planner judges which reference the run fixes; an absent or empty closes adds no line, and the comment never carries a closing line.' },
    { id: 'SD-77', step: 'Approvals', check: 'applyApprovalChoices', rule: 'run.approvals starts [] and holds the destructive changes the user approved, each {category, item} once, keyed by its category and item text; at each reply round, planning or tail, applyApprovalChoices applies the readReplyChoices of the user\'s own reply: a chosen option adds the items it lists, ask.items of its index when the ask sets items, else its destructive list, and removes every item only its sibling options list; a reply in the user\'s own words gives no choice and approves nothing, a decision the run took never changes the list, and a resume that replays the same replies builds the same list (issue 499).' },
    { id: 'SD-78', step: 'Approvals', check: 'listApprovalsBlock', rule: 'Each worker prompt and each validation fix prompt carries the approvals block, run.approvals as data, after its other blocks, and its data line names it the user\'s decision through dataBlocksSentence, joined to the user_answer reply when the fix prompt has one, only when run.approvals is not empty, so with no approval both prompts are byte for byte as before (issue 499).' },
    { id: 'SD-79', step: 'Review questions', check: 'askHeldReviewCall', rule: 'When the review run right after a call the run took, its user_answer decided_by run, returns blocked with a hold readGateHold reads, a stage of destructive-fix-gate or a blocker starting with the security-policy.md gate text, the run removes that call from run.taken and asks its question of the user: the lead is the code-built line saying local review held back the call the run took, then the lead of SD-37, and the question, shown as SD-37 shows it with its ask items, resolves through buildUndecidedAsk on the code-built brief with gate.safety true, so it is asked, never taken; the reply reruns local review with user_answer and no decided_by, a letter reply also updates run.approvals through the tail path, and a hold with no taken call right before it, any other block, or a hold after the user\'s reply stops as SD-36 says (issue 499).' },
    { id: 'SD-80', step: 'Launch', check: 'readDecisions', rule: 'The decisions launch arg is absent, giving [], or a list of 1 to maxDecisions() non-blank strings of at most maxDecisionLength() code points each, the user\'s own replies settled before launch, or the run blocks before any agent call; run.decisions keeps them, and listAnswerEntries(run) gives one entry per decision, through buildAnswerEntry, with the question \'Q1. A decision you settled before the run started.\', settled [\'Q1\'] and the decision word for word as reply, then run.answerLog, for the scope, plan, revise and review prompts alone, the review inputs carrying it as answers (SD-32); a decision never enters run.answerLog, its round numbers, resume_args, run.headRound or the resume note, and never changes run.approvals, which only in-run letter replies change, so with no decisions every prompt is as before (issue 500).' },
    { id: 'SD-81', step: 'Plan check retries', check: 'callCheckedPlanner', rule: 'Each plan-P and revise-R call goes through callCheckedPlanner: a result, after normalizePlanTitle, that describePlanProblem refuses and isFixableResult of lib/retry.js accepts, any result but a null one, an agent failure, and a planner\'s blocked outcome that fits its schema and gives a reason, goes back to the planner under label plan-P-fix-N or revise-R-fix-N, N from 1 to maxCheckRetries(), which is 2, with buildCheckFixPrompt of lib/retry.js: the first prompt with the line Fix your result per the check block. after its first line, and a check data block of the problem and up to maxCheckErrors(), which is 5, schema errors at its end; a result that describePlanProblem accepts still fails the check when hasDefectQuestion of lib/retry.js finds that decide(), kind planner_question at the run level, gives one of its questions a reason in neither askReasons() nor auto, such as malformed_brief for a recommended beyond_request option that is not strong with trivial or small effort, with the fixed problem A planner question fails the decision check, so the delivery stopped., so a defect in a question goes back to the planner and is never asked of the user (issue 549); a fixed retry goes on as a fitting first result does, with no pause before it, and a result still failing after maxCheckRetries() retries ends the run blocked with no further call and no question, through describeCheckLimit of lib/retry.js: the problem, then It stayed after 2 retries., then the report Next line.' },
    { id: 'SD-82', step: 'Ask Set', check: 'askReasons', rule: 'Only the closed Ask Set pauses the run (issue 549): askReasons() is hard_stop, table_surface, gate_irreversible, gate_architectural, gate_safety and no_recommendation, disjoint from listReasons(), beyond_request, outside_limits and repeats_surface, which a take lists for veto; the built script calls pauseForUser only in pauseDelivery, pauseDelivery only in askTails and runPlanningPass, pauseForRetry, a wait with needs_user false that asks nothing, only in waitForService (SD-84), pushes an ask only in resolveDecision and sets needs_user true only in lib/result.js; pauseDelivery throws on any ask whose reason is not in askReasons() and on a step_stop ask whose stop is neither approve nor fix_cause; so a run shaped as wf_d1cc3369-306, a strong trivial beyond-request planner question, plan files outside the scope limits README.md and web, a root-cluster local review and a remediation plan that repeats a surface outside those limits, reaches its pull request with no pause, and the pull request body lists under Decided for you the beyond-request take, the outside-limits take and the repeats-surface take.' },
    { id: 'SD-83', step: 'Loop caps', check: 'requiredGateIds', rule: 'A loop cap opens a draft pull request and asks nothing (issue 549): a max-iterations-reached or break-fix-break review (SD-36), a planner-escalation or root-cluster-suspected review at maxReplans() or maxReviewReplans() (SD-39), a blocked review past its waits (SD-84) and the gate rerun past maxGateReruns() (SD-27) each return {draft: reason}, and runGates keeps the first reason in gates.draft; from then requiredGateIds is validation alone, so validation still runs first on the head, local review never runs again, and the pull request step runs once validation holds on the head, with draft true in its inputs; the body and comment put the plain line This pull request is a draft: and the reason first in the run record, local review shows did not hold in the gates, and right after the gates an external part, Findings local review left open:, lists one line per run.open entry, its short finding id and its title through quoteOpenTitle, the longest prefix whose encodeUntrustedText form has a messageCost within maxExcerptLength(), followed by the plain words , shortened when cut, so 50 open findings of any schema-valid titles keep the part under 22,000 characters and the draft body within maxPullRequestTextLength(), only on a draft and only when run.open is not empty, so a title reaches only the pull request texts, never chat; the final message puts The pull request is a draft: and the reason in place of the held-gates line; the validation fix limit, the version-only fix limit and the worker needs_replan limit still ask, and injection-suspect stays terminal with no draft.' },
    { id: 'SD-84', step: 'Service waits', check: 'waitForService', rule: 'A blocked review whose retry_minutes is 1 or more waits out the outside service it names, asking nothing, while that time is within the waits left, maxServiceWaits() 6 less run.waits times maxWaitMinutes() 60, and the resume args fit (canCarry): with no reply for the next round it returns pauseForRetry, {needs_user false, retry_minutes, resume_args, message}, retry_minutes the stated time capped at maxWaitMinutes(), the message its lead naming the head and the wait, then the quoted blocker; the overlord resumes the same run with the reply retry, which goes into run.answerLog as the run\'s own wait, question the lead, settled [] and decided_by run, adds one to run.waits and reruns local review with the next count and no user_answer; a stated time past the waits left, including any once run.waits reaches maxServiceWaits(), or resume args that do not fit return {draft}, so the pull request opens as a draft (SD-83); a blocked review with no retry_minutes, or with 0, still asks one fix_cause step_stop question (SD-36), so a run shaped as wf_c443e159-abd, two Codex usage-limit blocks then a clean review, waits twice and opens a ready pull request with no user pause.' },
    { id: 'SD-85', step: 'Review replan model', check: 'callPassPlanner', rule: 'A pass whose replan data carries a review sends its plan-P call, each revise-R call and each of their -fix-N retries to hivemind:cerebrate on model sonnet, through plannerCallOptions with call.model; a sonnet result that passes the plan check and flags plan.remediation_gate.promotion_gate.architectural sends the same prompt once more on model opus, label plan-P-opus or revise-R-opus, whose checked result is the one the pass reads, and every later plan or revise call of the pass, -fix-N retries included, runs on opus with no further opus call; every plan and revise call of a pass with no review sets no model, so its options hold no model key and are byte for byte as before.' }
  ];
}
